const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const northernAfghanistan = ee.Geometry.Polygon(
    [[[64.5, 37.5],
      [64.5, 35.5],
      [70.0, 35.5],
      [70.0, 37.5],
      [64.5, 37.5]]]);

  const year2018_start = '2018-06-01';
  const year2018_end = '2018-08-31';

  const historical_start_year = 2000;
  const historical_end_year = 2013;
  const month_start = 6; // June
  const month_end = 8;   // August

  // Scale for reduceRegion (Landsat resolution)
  const scale = 30; // Meters

  // 2. Helper Functions
  // Function to mask clouds for Landsat 7 SR
  function maskL7Clouds(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1
  }

  // Function to mask clouds for Landsat 8 SR
  function maskL8Clouds(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    return image.addBands(image.normalizedDifference(['B5', 'B4']).rename('NDVI'));
  }

  // 3. Data Acquisition and Processing for 2018
  console.log("Processing 2018 data...");
  let l8_2018 = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
    .filterBounds(northernAfghanistan)
    .filterDate(year2018_start, year2018_end)
    .map(maskL8Clouds)
    .map(addNDVI)
    .select('NDVI');

  let l8_2018_size = l8_2018.size().getInfo();
  if (l8_2018_size === 0) {
    console.log("No Landsat 8 images found for June-August 2018.");
    console.log("C1");
    return;
  }
  console.log(`2018 Images (pre-mask): ${l8_2018_size}`);

  let ndvi_2018_median = l8_2018.median();

  // Check valid pixels for 2018
  let count_2018 = ndvi_2018_median.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northernAfghanistan,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count_2018 === 0 || count_2018 === null) {
    console.log("No valid pixels for 2018 after cloud masking.");
    console.log("C2");
    return;
  }
  console.log(`2018 Valid Pixels: ${count_2018}`);

  let mean_ndvi_2018 = ndvi_2018_median.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northernAfghanistan,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (mean_ndvi_2018 === null || isNaN(mean_ndvi_2018)) {
    console.log("2018 NDVI calculation failed (NaN/null result).");
    console.log("C3");
    return;
  }

  // 4. Data Acquisition and Processing for Historical Average (2000-2013)
  console.log("Processing historical data (2000-2013)...");
  let historical_yearly_ndvi = ee.ImageCollection([]);

  for (let year = historical_start_year; year <= historical_end_year; year++) {
    let start_date = ee.Date.fromYMD(year, month_start, 1);
    let end_date = ee.Date.fromYMD(year, month_end, 31);

    let l7_collection = ee.ImageCollection('LANDSAT/LE07/C01/T1_SR')
      .filterBounds(northernAfghanistan)
      .filterDate(start_date, end_date)
      .map(maskL7Clouds)
      .map(addNDVI)
      .select('NDVI');

    let current_year_size = l7_collection.size().getInfo();
    if (current_year_size === 0) {
      console.log(`Warning: No Landsat 7 images for ${year}. Skipping year.`);
      continue;
    }
    console.log(`  ${year} Images (pre-mask): ${current_year_size}`);

    let yearly_median = l7_collection.median();
    historical_yearly_ndvi = historical_yearly_ndvi.merge(ee.ImageCollection([yearly_median]));
  }

  let historical_collection_size = historical_yearly_ndvi.size().getInfo();
  if (historical_collection_size === 0) {
    console.log("No valid historical yearly median images after processing.");
    console.log("C1");
    return;
  }

  let ndvi_historical_median = historical_yearly_ndvi.median();

  // Check valid pixels for historical average
  let count_historical = ndvi_historical_median.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northernAfghanistan,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count_historical === 0 || count_historical === null) {
    console.log("No valid pixels for historical period after cloud masking.");
    console.log("C2");
    return;
  }
  console.log(`Historical Valid Pixels: ${count_historical}`);

  let mean_ndvi_historical = ndvi_historical_median.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northernAfghanistan,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (mean_ndvi_historical === null || isNaN(mean_ndvi_historical)) {
    console.log("Historical NDVI calculation failed (NaN/null result).");
    console.log("C3");
    return;
  }

  // 5. Comparison and Final Answer
  console.log(`2018 (Jun-Aug) Avg NDVI: ${mean_ndvi_2018.toFixed(4)}`);
  console.log(`2000-2013 (Jun-Aug) Avg NDVI: ${mean_ndvi_historical.toFixed(4)}`);

  if (mean_ndvi_2018 < mean_ndvi_historical) {
    console.log("A"); // Yes, NDVI decreased
  } else {
    console.log("B"); // No, NDVI did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
